type WeatherSeasonWeight struct {
	Id SeasonId `json:"id"`

	Weight EntryWeight `json:"weight"`
}

// WeatherSeverity 天候の寒さの厳しさ。奥地ほど厳しい天候を厚くし、冬と奥地で長引かせるのに使う
type WeatherSeverity = int

// WeatherTempModifier 天候による世界温度への加算。℃
type WeatherTempModifier = int

// WeatherVisionDelta 天候による視程レンジへの加算。タイル。負で狭くなる
type WeatherVisionDelta = int

// Weight 重量。単位付き文字列で指定する。例: "500 g" "2 kg" "1 mg"
type Weight = string

// YardDepth 入口側に空ける前庭の奥行き。タイル
type YardDepth = int32

// Zone 市街地の地区
type Zone string

// Defines values for Zone.
const (
	Downtown    Zone = "downtown"
	Industrial  Zone = "industrial"
	Residential Zone = "residential"
)

// Valid indicates whether the value is a known member of the Zone enum.
func (e Zone) Valid() bool {
	switch e {
	case Downtown:
		return true
	case Industrial:
		return true
	case Residential:
		return true
	default:
		return false
	}
}

// ZoneValues は Zone の値を、スキーマに書いた順に返す。
func ZoneValues() []Zone {
	return []Zone{Downtown, Residential, Industrial}
}
